function SubjectJourney({ s }) {
  const { lang } = useQ();
  const [open, setOpen] = useState(false);
  const j = JOURNEYS[s.id];
  if (!j) return null;
  return (
    <div className="mb-8 rounded-3xl overflow-hidden relative" style={{ background: "linear-gradient(135deg, " + s.hue + "26, " + s.hue + "0a)", border: "1px solid " + s.hue + "38" }}>
      <div className="p-6 sm:p-8">
        <div className="text-xs font-extrabold uppercase tracking-widest mb-2" style={{ color: s.hue }}>{lang === "mn" ? "Аялал" : "The journey"}</div>
        <h2 className="text-2xl sm:text-3xl font-extrabold text-white mb-3" style={{ letterSpacing: "-0.02em" }}>{j.tag[lang]}</h2>
        <p className="text-indigo-100 leading-relaxed max-w-2xl">{j.intro[lang]}</p>
        {!open && (
          <button onClick={() => setOpen(true)} className="mt-5 px-5 py-2.5 rounded-full font-extrabold text-sm text-white inline-flex items-center gap-2 hover:-translate-y-0.5 transition-transform" style={{ background: s.hue }}>
            {lang === "mn" ? "Аялалыг эхлүүл" : "Begin the journey"} <ChevronDown size={16} />
          </button>
        )}
        {open && (
          <div className="mt-6 space-y-2.5 q-fade-up">
            {j.levels.map((lv, i) => (
              <div key={i} className="rounded-2xl p-4" style={{ background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.1)" }}>
                <div className="text-xs font-extrabold uppercase tracking-wide mb-1" style={{ color: s.hue }}>{lv.g[lang]}</div>
                <div className="text-sm text-indigo-100 leading-relaxed">{lv.t[lang]}</div>
              </div>
            ))}
            <div className="rounded-2xl p-5 text-center" style={{ background: s.hue + "26", border: "1px solid " + s.hue + "4d" }}>
              <div className="text-lg font-extrabold text-white mb-2 leading-snug">{j.close[lang]}</div>
              <div className="text-sm font-bold text-indigo-100">{j.people.join("  ·  ")}</div>
              <div className="text-xs text-indigo-300 mt-1.5">{lang === "mn" ? "Тэд бүгд асуултаас эхэлсэн." : "They all started by asking questions."}</div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
function SubjectPage() {
  const { t, lang, go, subjectId, completed, pathId, setPathId, user } = useQ();
  const s = DB.subjects.find((x) => x.id === subjectId) || DB.subjects[0];
  const hasPaths = Array.isArray(s.paths) && s.paths.length > 0;
  const path = hasPaths ? s.paths.find((p) => p.id === pathId) : null;

  /* ── LEVEL 1: choose a learning path (cards) ── */
  if (hasPaths && !path) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-10">
        <Breadcrumb items={[{ label: t.subjectsTitle, onClick: () => go("learning") }, { label: s.name[lang] }]} />
        <div className="flex items-center gap-4 mb-3">
          <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-3xl" style={{ background: s.hue + "18" }}><Ic id={s.id} size={30} color={s.hue} /></div>
          <div>
            <h1 className="text-3xl font-extrabold text-white">{s.name[lang]}</h1>
            <div className="text-indigo-200 text-sm mt-0.5">{s.desc[lang]}</div>
          </div>
        </div>
        <p className="text-sm font-bold text-slate-600 mb-7">{t.choosePath}</p>
        <div className="grid md:grid-cols-3 gap-5">
          {s.paths.map((p, i) => {
            const bs = pathBranches(s, p);
            const nodeCount = bs.reduce((x, b) => x + b.nodes.length, 0);
            return (
              <button key={p.id} onClick={() => { setPathId(p.id); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
                className="group relative text-left p-7 pt-8 rounded-3xl border border-indigo-100 q-lp hover:border-violet-300 q-fade-up q-cardglow flex flex-col overflow-hidden"
                style={{ boxShadow: "0 16px 40px -22px rgba(79,70,229,.45)", animationDelay: i * 80 + "ms" }}>
                <div className="absolute top-0 left-0 right-0" style={{ height: 5, background: s.hue }} />
                <div className="w-16 h-16 rounded-2xl flex items-center justify-center mb-5" style={{ background: s.hue + "14" }}><Ic id={p.id} size={34} color={s.hue} /></div>
                <div className="font-extrabold text-xl text-slate-900">{p.name[lang]}</div>
                <div className="text-sm text-slate-800 mt-2 leading-relaxed flex-1">{p.desc[lang]}</div>
                <div className="mt-5 flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wide text-slate-700">{bs.length} {t.tracksLabel} · {nodeCount} {t.nodesLabel}</span>
                  <span className="inline-flex items-center gap-1 text-sm font-extrabold group-hover:gap-2 transition-all" style={{ color: s.hue }}>{t.explorePath} <ArrowRight size={15} /></span>
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  /* ── LEVEL 2: choose a specialization within a path (button grid) ── */
  if (hasPaths && path) {
    const bs = pathBranches(s, path);
    return (
      <div className="max-w-6xl mx-auto px-4 py-10">
        <Breadcrumb items={[
          { label: t.subjectsTitle, onClick: () => go("learning") },
          { label: s.name[lang], onClick: () => setPathId(null) },
          { label: path.name[lang] },
        ]} />
        <div className="flex items-center gap-4 mb-2">
          <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-3xl" style={{ background: s.hue + "18" }}><Ic id={path.id} size={30} color={s.hue} /></div>
          <div>
            <h1 className="text-2xl sm:text-3xl font-extrabold text-white">{path.name[lang]}</h1>
            <div className="text-indigo-200 text-sm mt-0.5 max-w-2xl">{path.desc[lang]}</div>
          </div>
        </div>
        <p className="text-sm font-bold text-slate-600 mb-6 mt-3">{t.chooseSpec}</p>
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {bs.map((b, i) => {
            const pr = branchProgress(b, completed);
            const hours = b.nodes.reduce((x, n) => x + n.h, 0);
            return (
              <button key={b.id} onClick={() => go("tree", b.id)}
                className="text-left p-5 rounded-2xl border border-indigo-100 q-lp hover:border-violet-300 q-fade-up q-cardglow"
                style={{ animationDelay: i * 45 + "ms" }}>
                <div className="flex items-center gap-3">
                  <div className="w-11 h-11 rounded-xl flex items-center justify-center text-2xl shrink-0" style={{ background: s.hue + "14" }}><Ic id={b.id} subject={s.id} size={24} color={s.hue} /></div>
                  <div className="min-w-0 flex-1">
                    <div className="font-extrabold text-slate-900 leading-tight truncate">{b.name[lang]}</div>
                    <div className="text-xs font-semibold text-slate-700 mt-0.5">{b.nodes.length} {t.nodesLabel} · ≈{Math.round(hours)} {t.hoursShort}</div>
                  </div>
                  <ArrowRight size={16} className="text-slate-500 shrink-0" />
                </div>
                <div className="text-xs text-slate-800 mt-2.5 leading-snug line-clamp-2">{b.desc[lang]}</div>
                {pr.done > 0 && <div className="mt-3"><PBar pct={pr.pct} /></div>}
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  /* ── Classic single-level layout (subjects without paths, e.g. Physics) ── */
  return (
    <div className="max-w-6xl mx-auto px-4 py-10">
      <Breadcrumb items={[{ label: t.subjectsTitle, onClick: () => go("learning") }, { label: s.name[lang] }]} />
      <div className="flex items-center gap-4 mb-8">
        <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-3xl" style={{ background: s.hue + "18" }}><Ic id={s.id} size={30} color={s.hue} /></div>
        <div>
          <h1 className="text-3xl font-extrabold text-white">{s.name[lang]}</h1>
          <div className="text-indigo-200 text-sm mt-0.5">{s.desc[lang]}</div>
        </div>
      </div>
      <div className="grid sm:grid-cols-2 gap-5">
        {(s.branches || []).map((b, i) => {
          const pr = branchProgress(b, completed);
          const hours = b.nodes.reduce((x, n) => x + n.h, 0);
          return (
            <button key={b.id} onClick={() => go("tree", b.id)}
              className="text-left p-6 rounded-3xl border border-indigo-100 q-lp hover:border-violet-300 q-fade-up q-cardglow"
              style={{ boxShadow: "0 12px 34px -20px rgba(79,70,229,.4)", animationDelay: i * 60 + "ms" }}>
              <div className="flex items-start justify-between">
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl" style={{ background: s.hue + "14" }}><Ic id={b.id} subject={s.id} size={24} color={s.hue} /></div>
                <span className="px-2.5 py-1 rounded-full text-xs font-extrabold bg-emerald-50 text-emerald-600">{t.liveBadge}</span>
              </div>
              <div className="mt-4 font-extrabold text-lg text-slate-900">{b.name[lang]}</div>
              <div className="text-sm text-slate-800 mt-1 leading-snug">{b.desc[lang]}</div>
              <div className="mt-3 text-xs font-semibold text-slate-700">{b.nodes.length} {t.nodesLabel} · ≈{Math.round(hours)} {t.hoursShort}</div>
              {pr.done > 0 && <div className="mt-3"><PBar pct={pr.pct} /></div>}
              <div className="mt-4 inline-flex items-center gap-1.5 text-sm font-bold" style={{ color: s.hue }}>{t.openTree} <ArrowRight size={15} /></div>
            </button>
          );
        })}
      </div>
      {(s.planned || []).length > 0 && (
        <div className="mt-10">
          <div className="text-xs font-extrabold uppercase tracking-widest text-indigo-300 mb-3">{t.plannedLabel}</div>
          <div className="flex flex-wrap gap-2">
            {s.planned.map((p, i) => (
              <span key={i} className="px-3.5 py-2 rounded-full border border-dashed border-indigo-200 text-xs font-bold text-slate-700 q-lp">{p[lang]}</span>
            ))}
          </div>
          <div className="text-xs text-slate-600 mt-3 max-w-xl">{t.plannedNote}</div>
        </div>
      )}
    </div>
  );
}

/* ═══ MODULE: components/TreePage.jsx ═══ */
function TreePage() {
  const { t, lang, branchId, completed, setDrawerNode, go, setPathId, user } = useQ();
  const found = findBranch(branchId) || { subject: DB.subjects[0], branch: DB.subjects[0].branches[0] };
  const { subject, branch: p } = found;
  const layout = useMemo(() => {
    const nodes = p.nodes; const byId = {}; nodes.forEach((n) => (byId[n.id] = n));
    const memo = {};
    const depth = (n) => { if (memo[n.id] != null) return memo[n.id]; memo[n.id] = 0; const inl = (n.prereqs || []).filter((pid) => byId[pid] && pid !== n.id); const d = inl.length ? 1 + Math.max(...inl.map((pid) => depth(byId[pid]))) : 0; memo[n.id] = d; return d; };
    const ordered = nodes.map((n, idx) => ({ n, idx, d: depth(n) })).sort((a, b) => a.d - b.d || a.idx - b.idx).map((x) => x.n);
    const ROW = 148, AMP = 112, CX = 250; const pos = {};
    ordered.forEach((n, i) => { pos[n.id] = [CX + AMP * Math.sin(i * 0.7), 84 + i * ROW]; });
    return { ordered, pos, W: CX + AMP + 130, H: 84 + ordered.length * ROW + 40 };
  }, [p.id]);
  const boxRef = useRef(null);
  const [scale, setScale] = useState(0.8);
  const [off, setOff] = useState({ x: 20, y: 24 });
  const drag = useRef(null);
  const moved = useRef(false);
  const fit = () => {
    const cw = boxRef.current ? boxRef.current.clientWidth : 900;
    const s = Math.max(0.35, Math.min(1, (cw - 40) / layout.W));
    setScale(s); setOff({ x: (cw - layout.W * s) / 2, y: 24 });
  };
  useEffect(fit, [branchId]);
  const pr = branchProgress(p, completed);
  const statusOf = (n) => (completed[n.id] ? "done" : isNodeAvailable(n, completed) ? "avail" : "locked");
  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      {(() => {
        const treePath = (subject.paths || []).find((pp) => (pp.branches || []).includes(branchId));
        const crumbs = [
          { label: t.subjectsTitle, onClick: () => { setPathId(null); go("learning"); } },
          { label: subject.name[lang], onClick: () => { setPathId(null); go("subject", subject.id); } },
        ];
        if (treePath) crumbs.push({ label: treePath.name[lang], onClick: () => { setPathId(treePath.id); go("subject", subject.id); } });
        crumbs.push({ label: p.name[lang] });
        return <Breadcrumb items={crumbs} />;
      })()}
      <div className="mb-6 rounded-3xl p-6 sm:p-7 relative overflow-hidden" style={{ background: "linear-gradient(135deg, " + subject.hue + "26, " + subject.hue + "0a)", border: "1px solid " + subject.hue + "38" }}>
        <div className="absolute -right-10 -top-10 w-44 h-44 rounded-full pointer-events-none" style={{ background: "radial-gradient(circle, " + subject.hue + "33, transparent 70%)" }} />
        <div className="relative flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-start gap-3.5 min-w-0 flex-1">
            <div className="w-14 h-14 shrink-0 rounded-2xl flex items-center justify-center text-2xl" style={{ background: subject.hue + "26" }}><Ic id={p.id} subject={subject.id} size={28} color={subject.hue} /></div>
            <div className="min-w-0">
              <div className="text-xs font-extrabold uppercase tracking-widest mb-1" style={{ color: subject.hue }}>{subject.name[lang]} · {lang === "mn" ? "Танилцуулга" : "What you'll explore"}</div>
              <h1 className="text-2xl sm:text-3xl font-extrabold text-white leading-tight" style={{ letterSpacing: "-0.02em" }}>{p.name[lang]}</h1>
              <p className="text-sm sm:text-base text-indigo-100 mt-2 leading-relaxed max-w-2xl">{p.desc[lang]}</p>
              <div className="text-xs font-bold mt-2.5" style={{ color: subject.hue }}>{pr.total} {lang === "mn" ? "сэдэв" : "topics"}{p.nodes && p.nodes.length ? " · " + (lang === "mn" ? "эхлэл: " : "start: ") + p.nodes[0].name[lang] : ""}</div>
            </div>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            <div className="w-36"><PBar pct={pr.pct} gold /></div>
            <span className="text-sm font-extrabold text-amber-500">{pr.done}/{pr.total}</span>
          </div>
        </div>
      </div>
      <div ref={boxRef} className="relative overflow-hidden rounded-3xl border border-indigo-100"
        style={{ height: "66vh", minHeight: 460, touchAction: "none", cursor: "grab", background: "linear-gradient(180deg,#e8e2f8 0%,#dad2f3 100%)", boxShadow: "inset 0 0 80px rgba(99,102,241,.1)" }}
        onPointerDown={(e) => { drag.current = { sx: e.clientX, sy: e.clientY, ox: off.x, oy: off.y }; moved.current = false; e.currentTarget.setPointerCapture(e.pointerId); }}
        onPointerMove={(e) => { if (drag.current) { const dx = e.clientX - drag.current.sx, dy = e.clientY - drag.current.sy; if (Math.abs(dx) + Math.abs(dy) > 6) moved.current = true; setOff({ x: drag.current.ox + dx, y: drag.current.oy + dy }); } }}
        onPointerUp={() => (drag.current = null)} onPointerCancel={() => (drag.current = null)}>
        <Starfield count={22} />
        <div className="absolute top-3 right-3 z-10 flex flex-col gap-1.5">
          {[[<Plus size={16} key="p" />, () => setScale((s) => Math.min(1.6, s + 0.15))],
            [<Minus size={16} key="m" />, () => setScale((s) => Math.max(0.35, s - 0.15))],
            [<RotateCcw size={14} key="r" />, fit]].map(([ic, fn], i) => (
            <button key={i} onClick={fn} className="w-9 h-9 rounded-xl q-lp border border-indigo-100 shadow-md flex items-center justify-center text-slate-600 hover:text-indigo-700 hover:border-violet-300">{ic}</button>
          ))}
        </div>
        <div className="absolute" style={{ transform: `translate(${off.x}px, ${off.y}px) scale(${scale})`, transformOrigin: "0 0", width: layout.W, height: layout.H }}>
          <svg width={layout.W} height={layout.H} className="absolute" style={{ left: 0, top: 0 }}>
            {layout.ordered.slice(0, -1).map((n, i) => {
              const next = layout.ordered[i + 1];
              const [x1, y1] = layout.pos[n.id], [x2, y2] = layout.pos[next.id];
              const mid = (y1 + y2) / 2;
              const bothDone = completed[n.id] && completed[next.id];
              const lit = completed[n.id];
              return (
                <path key={n.id + next.id} d={`M ${x1} ${y1 + 34} C ${x1} ${mid}, ${x2} ${mid}, ${x2} ${y2 - 34}`}
                  fill="none" stroke="#111827"
                  strokeWidth={bothDone ? 3 : 2} strokeDasharray={lit ? "none" : "5 6"} opacity={bothDone ? 0.92 : lit ? 0.78 : 0.55} />
              );
            })}
          </svg>
          {p.nodes.map((n) => {
            const st = statusOf(n);
            const ext = n.prereqs.filter((pid) => !p.nodes.find((x) => x.id === pid));
            return (
              <button key={n.id} onClick={() => { if (moved.current) return; setDrawerNode(ALL_NODES[n.id]); }}
                className={cx("absolute w-44 rounded-2xl p-3 text-left transition-all border-2",
                  st === "done" && "bg-gradient-to-br from-indigo-600 to-violet-600 border-transparent text-white shadow-lg",
                  st === "avail" && "q-lp border-violet-400 text-slate-900 q-glow shadow-md hover:-translate-y-1",
                  st === "locked" && "q-lp border-slate-200 text-slate-600 opacity-80")}
                style={{ left: layout.pos[n.id][0], top: layout.pos[n.id][1], transform: "translate(-50%,-50%)" }}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className={cx("w-6 h-6 rounded-full flex items-center justify-center text-xs font-extrabold",
                    st === "done" ? "q-lp text-violet-600" : st === "avail" ? "bg-gradient-to-br from-indigo-500 to-violet-600 text-white" : "bg-violet-100 text-violet-600")}>
                    {st === "done" ? <Check size={13} strokeWidth={3.5} /> : st === "locked" ? <Lock size={11} /> : <Star size={13} fill="currentColor" strokeWidth={0} />}
                  </span>
                  <span className={cx("text-xs font-extrabold", st === "done" ? "text-amber-300" : "text-amber-600")}>+{n.xp} XP</span>
                </div>
                <div className="font-extrabold text-sm leading-tight">{n.name[lang]}</div>
                <div className={cx("text-xs mt-1 font-semibold", st === "done" ? "text-indigo-100" : "text-slate-700")}>
                  ≈{n.h} {t.hoursShort}{ext.length > 0 && " · 🔗"}
                </div>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/* ═══ MODULE: components/NodeDrawer.jsx ═══ */
const RES_ICONS = { video: <Play size={16} className="text-red-500" />, course: <BookOpen size={16} className="text-indigo-500" />, book: <FileText size={16} className="text-slate-700" />, practice: <PenLine size={16} className="text-emerald-500" />, sim: <Gamepad2 size={16} className="text-violet-500" /> };
