function ReadinessRing({ pct, pctColor = "#1e1b4b" }) {
  const r = 62, c = 2 * Math.PI * r;
  return (
    <svg width="160" height="160" viewBox="0 0 160 160">
      <circle cx="80" cy="80" r={r} fill="none" stroke="rgba(148,163,255,.22)" strokeWidth="13" />
      <circle cx="80" cy="80" r={r} fill="none" stroke="url(#rg)" strokeWidth="13" strokeLinecap="round"
        strokeDasharray={c} strokeDashoffset={c - (c * pct) / 100} transform="rotate(-90 80 80)" style={{ transition: "stroke-dashoffset 1s ease" }} />
      <defs><linearGradient id="rg" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#818cf8" /><stop offset="100%" stopColor="#c084fc" /></linearGradient></defs>
      <text x="80" y="76" textAnchor="middle" fontSize="30" fontWeight="800" fill={pctColor}>{pct}%</text>
      <text x="80" y="98" textAnchor="middle" fontSize="11" fontWeight="700" fill="#a78bfa">✦</text>
    </svg>
  );
}
